// Check connection health for each session
const sessionData = $input.first().json;
const { sessionId } = sessionData;

// Get WebSocket connections for this session
const connections = await getWebSocketConnections(sessionId);

// Check connection health
const connectionHealth = {
  sessionId,
  totalConnections: connections.length,
  activeConnections: connections.filter(c => c.status === 'connected').length,
  staleConnections: connections.filter(c => {
    const lastActivity = new Date(c.lastActivity);
    const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000);
    return lastActivity < fiveMinutesAgo;
  }).length,
  averageLatency: calculateAverageLatency(connections),
  healthScore: calculateHealthScore(connections)
};

async function getWebSocketConnections(sessionId) {
  // Get WebSocket connections from database
  return [
    {
      connectionId: 'conn_001',
      userId: 'user_001',
      status: 'connected',
      lastActivity: new Date().toISOString(),
      latency: 45
    },
    {
      connectionId: 'conn_002',
      userId: 'user_002', 
      status: 'connected',
      lastActivity: new Date(Date.now() - 30 * 1000).toISOString(),
      latency: 52
    }
  ];
}

function calculateAverageLatency(connections) {
  const latencies = connections
    .filter(c => c.status === 'connected' && c.latency)
    .map(c => c.latency);

  if (latencies.length === 0) return 0;
  return Math.round(latencies.reduce((sum, lat) => sum + lat, 0) / latencies.length);
}

function calculateHealthScore(connections) {
  const activeConnections = connections.filter(c => c.status === 'connected').length;
  const totalConnections = connections.length;
  const avgLatency = calculateAverageLatency(connections);

  let score = 100;

  // Penalize disconnected connections
  score -= ((totalConnections - activeConnections) / totalConnections) * 30;

  // Penalize high latency
  if (avgLatency > 1000) score -= 30;
  else if (avgLatency > 500) score -= 15;
  else if (avgLatency > 200) score -= 5;

  return Math.max(0, Math.round(score));
}

return { json: connectionHealth };

// Check resource usage for sessions
const healthData = $input.first().json;
const { sessionId } = healthData;

// Get resource allocation and usage
const resourceData = await getResourceUsage(sessionId);

const resourceHealth = {
  ...healthData,
  resources: {
    memory: {
      allocated: resourceData.memory.allocated,
      used: resourceData.memory.used,
      percentage: (parseFloat(resourceData.memory.used) / parseFloat(resourceData.memory.allocated)) * 100
    },
    cpu: {
      allocated: resourceData.cpu.allocated,
      current: resourceData.cpu.current,
      percentage: (parseFloat(resourceData.cpu.current) / parseFloat(resourceData.cpu.allocated)) * 100
    },
    bandwidth: {
      allocated: resourceData.bandwidth.allocated,
      current: resourceData.bandwidth.current,
      percentage: calculateBandwidthPercentage(resourceData.bandwidth.current, resourceData.bandwidth.allocated)
    },
    aiAgents: {
      allocated: resourceData.aiAgents.allocated,
      active: resourceData.aiAgents.active
    }
  },
  resourceScore: calculateResourceScore(resourceData)
};

async function getResourceUsage(sessionId) {
  // Get resource usage from monitoring system
  return {
    memory: {
      allocated: '512MB',
      used: '384MB'
    },
    cpu: {
      allocated: '0.5',
      current: '0.3'
    },
    bandwidth: {
      allocated: '1Mbps',
      current: '750kbps'
    },
    aiAgents: {
      allocated: 2,
      active: 1
    }
  };
}

function calculateBandwidthPercentage(current, allocated) {
  const currentBps = parseBandwidth(current);
  const allocatedBps = parseBandwidth(allocated);
  return (currentBps / allocatedBps) * 100;
}

function parseBandwidth(bandwidth) {
  const value = parseInt(bandwidth);
  if (bandwidth.includes('Mbps')) return value * 1000000;
  if (bandwidth.includes('kbps')) return value * 1000;
  if (bandwidth.includes('bps')) return value;
  return 0;
}

function calculateResourceScore(resourceData) {
  let score = 100;

  // Memory usage
  const memoryUsage = (parseFloat(resourceData.memory.used) / parseFloat(resourceData.memory.allocated)) * 100;
  if (memoryUsage > 90) score -= 30;
  else if (memoryUsage > 75) score -= 15;

  // CPU usage
  const cpuUsage = (parseFloat(resourceData.cpu.current) / parseFloat(resourceData.cpu.allocated)) * 100;
  if (cpuUsage > 80) score -= 20;

  // Bandwidth usage
  const bandwidthUsage = calculateBandwidthPercentage(resourceData.bandwidth.current, resourceData.bandwidth.allocated);
  if (bandwidthUsage > 90) score -= 15;

  return Math.max(0, Math.round(score));
}

return { json: resourceHealth };

// Check service health
const resourceData = $input.first().json;
const { sessionId } = resourceData;

// Check health of dependent services
const serviceChecks = await Promise.all([
  checkServiceHealth('voice-service', sessionId),
  checkServiceHealth('ai-service', sessionId),
  checkServiceHealth('event-bus', sessionId),
  checkServiceHealth('database', sessionId)
]);

const serviceHealth = {
  ...resourceData,
  services: serviceChecks.reduce((acc, service) => {
    acc[service.name] = {
      status: service.status,
      responseTime: service.responseTime,
      lastCheck: service.lastCheck,
      error: service.error
    };
    return acc;
  }, {}),
  serviceScore: calculateServiceScore(serviceChecks)
};

async function checkServiceHealth(serviceName, sessionId) {
  const startTime = Date.now();

  try {
    // Make health check request to service
    const response = await makeHealthCheckRequest(serviceName, sessionId);
    const responseTime = Date.now() - startTime;

    return {
      name: serviceName,
      status: 'healthy',
      responseTime,
      lastCheck: new Date().toISOString(),
      error: null
    };
  } catch (error) {
    const responseTime = Date.now() - startTime;

    return {
      name: serviceName,
      status: 'unhealthy',
      responseTime,
      lastCheck: new Date().toISOString(),
      error: error.message
    };
  }
}

async function makeHealthCheckRequest(serviceName, sessionId) {
  // Make actual health check request
  // For now, simulate responses
  const responses = {
    'voice-service': { status: 'ok', latency: 23 },
    'ai-service': { status: 'ok', latency: 145 },
    'event-bus': { status: 'ok', latency: 12 },
    'database': { status: 'ok', latency: 5 }
  };

  const response = responses[serviceName];
  if (!response || response.latency > 5000) {
    throw new Error(`Service ${serviceName} is not responding`);
  }

  return response;
}

function calculateServiceScore(serviceChecks) {
  const healthyServices = serviceChecks.filter(s => s.status === 'healthy').length;
  const totalServices = serviceChecks.length;

  return Math.round((healthyServices / totalServices) * 100);
}

return { json: serviceHealth };

// Calculate overall health score and prepare health report
const healthData = $input.first().json;
const { sessionId } = healthData;

const overallHealthScore = Math.round(
  ((healthData.healthScore || 0) + 
   (healthData.resourceScore || 0) + 
   (healthData.serviceScore || 0)) / 3
);

const healthReport = {
  sessionId,
  timestamp: new Date().toISOString(),
  overallHealthScore,
  status: overallHealthScore >= 80 ? 'healthy' : 
          overallHealthScore >= 60 ? 'warning' : 'critical',
  details: {
    connections: {
      total: healthData.totalConnections,
      active: healthData.activeConnections,
      stale: healthData.staleConnections,
      averageLatency: healthData.averageLatency,
      score: healthData.healthScore
    },
    resources: healthData.resources,
    services: healthData.services
  },
  alerts: generateAlerts(healthData)
};

function generateAlerts(healthData) {
  const alerts = [];

  // Connection alerts
  if (healthData.staleConnections > 0) {
    alerts.push({
      type: 'stale_connections',
      severity: 'warning',
      message: `${healthData.staleConnections} stale connections detected`,
      count: healthData.staleConnections
    });
  }

  // Resource alerts
  if (healthData.resources.memory.percentage > 90) {
    alerts.push({
      type: 'high_memory_usage',
      severity: 'critical',
      message: `Memory usage at ${Math.round(healthData.resources.memory.percentage)}%`,
      value: healthData.resources.memory.percentage
    });
  }

  if (healthData.resources.cpu.percentage > 80) {
    alerts.push({
      type: 'high_cpu_usage',
      severity: 'warning',
      message: `CPU usage at ${Math.round(healthData.resources.cpu.percentage)}%`,
      value: healthData.resources.cpu.percentage
    });
  }

  // Service alerts
  Object.entries(healthData.services).forEach(([serviceName, service]) => {
    if (service.status === 'unhealthy') {
      alerts.push({
        type: 'service_down',
        severity: 'critical',
        message: `Service ${serviceName} is down`,
        service: serviceName,
        error: service.error
      });
    }
  });

  return alerts;
}

return { json: healthReport };
